def junit(folder):
 latest={}
 for p in sorted(folder.glob('*.xml'),key=lambda p:p.stat().st_mtime):
  try: tree=ET.parse(p)
  except ET.ParseError: continue
  for t in tree.iter('testcase'):
   cls=t.get('class',t.get('classname',''));name=t.get('name','')
   if not cls:continue
   status='FAIL' if t.find('failure') is not None else 'ERROR' if t.find('error') is not None else 'SKIP' if t.find('skipped') is not None else 'PASS'
   latest[cls+'::'+name]={'status':status,'assertions':int(t.get('assertions',0)),'evidence':str(p)}
 return latest
